190	class WinGetSource
191	{
192	    [DscProperty(Key, Mandatory)]
193	    [string]$Name
194	    
195	    [DscProperty(Mandatory)]
196	    [string]$Argument
197	    
198	    [DscProperty()]
199	    [string]$Type
200	    
201	    [DscProperty()]
202	    [WinGetTrustLevel]$TrustLevel = [WinGetTrustLevel]::Undefined
203	    
204	    [DscProperty()]
205	    [nullable[bool]]$Explicit = $null
206	    
207	    [DscProperty()]
208	    [nullable[int]]$Priority = $null
209	
210	    [DscProperty()]
211	    [WinGetEnsure]$Ensure = [WinGetEnsure]::Present
212	
213	    [WinGetSource] Get()
214	    {
215	        if ([String]::IsNullOrWhiteSpace($this.Name))
216	        {
217	            throw "A value must be provided for WinGetSource::Name"
218	        }
219	
220	        $currentSource = $null
221	
222	        try {
223	            $currentSource = Get-WinGetSource -Name $this.Name
224	        }
225	        catch {
226	        }
227	
228	        $result = [WinGetSource]::new()
229	
230	        if ($currentSource)
231	        {
232	            $result.Ensure = [WinGetEnsure]::Present
233	            $result.Name = $currentSource.Name
234	            $result.Argument = $currentSource.Argument
235	            $result.Type = $currentSource.Type
236	            $result.TrustLevel = $currentSource.TrustLevel
237	            $result.Explicit = $currentSource.Explicit
238	            $result.Priority = $currentSource.Priority
239	        }
240	        else
241	        {
242	            $result.Ensure = [WinGetEnsure]::Absent
243	            $result.Name = $this.Name
244	        }
245	
246	        return $result
247	    }
248	
249	    [bool] Test()
250	    {
251	        return $this.TestAgainstCurrent($this.Get())
252	    }
253	
254	    [void] Set()
255	    {
256	        Assert-IsAdministrator
257	
258	        $currentSource = $this.Get()
259	
260	        $removeSource = $false
261	        $resetSource = $false
262	        $addSource = $false
263	
264	        if ($this.Ensure -eq [WinGetEnsure]::Present)
265	        {
266	            if ($currentSource.Ensure -eq [WinGetEnsure]::Present)
267	            {
268	                if (-not $this.TestAgainstCurrent($currentSource))
269	                {
270	                    $resetSource = $true
271	                    $addSource = $true
272	                }
273	                # else in desired state
274	            }
275	            else
276	            {
277	                $addSource = $true
278	            }
279	        }
280	        else
281	        {
282	            if ($currentSource.Ensure -eq [WinGetEnsure]::Present)
283	            {
284	                $removeSource = $true
285	            }
286	            # else in desired state (Absent)
287	        }
288	
289	        if ($removeSource)
290	        {
291	            Remove-WinGetSource -Name $this.Name
292	        }
293	        # Only remove OR reset should be true, not both
294	        elseif ($resetSource)
295	        {
296	            Reset-WinGetSource -Name $this.Name
297	        }
298	
299	        if ($addSource)
300	        {
301	            $hashArgs = @{
302	                Name = $this.Name
303	                Argument = $this.Argument
304	            }
305	
306	            if (-not [string]::IsNullOrWhiteSpace($this.Type))
307	            {
308	                $hashArgs.Add("Type", $this.Type)
309	            }
310	
311	            if ($this.TrustLevel -ne [WinGetTrustLevel]::Undefined)
312	            {
313	                $hashArgs.Add("TrustLevel", $this.TrustLevel)
314	            }
315	
316	            if ($null -ne $this.Explicit)
317	            {
318	                $hashArgs.Add("Explicit", $this.Explicit)
319	            }
320	
321	            if ($null -ne $this.Priority)
322	            {
323	                $hashArgs.Add("Priority", $this.Priority)
324	            }
325	
326	            Add-WinGetSource @hashArgs
327	        }
328	    }
329	    
330	    # Test $this against a value retrieved from Get
331	    # We don't need to check Name because it is the Key for Get
332	    [bool] hidden TestAgainstCurrent([WinGetSource]$currentSource)
333	    {
334	        if ($this.Ensure -eq [WinGetEnsure]::Absent -and
335	            $currentSource.Ensure -eq [WinGetEnsure]::Absent)
336	        {
337	            return $true
338	        }
339	
340	        if ($this.Ensure -ne $currentSource.Ensure -or
341	            $this.Argument -ne $currentSource.Argument)
342	        {
343	            return $false
344	        }
345	
346	        if (-not([string]::IsNullOrWhiteSpace($this.Type)) -and
347	            $this.Type -ne $currentSource.Type)
348	        {
349	            return $false
350	        }
351	
352	        if ($this.TrustLevel -ne [WinGetTrustLevel]::Undefined -and
353	            $this.TrustLevel -ne $currentSource.TrustLevel)
354	        {
355	            return $false
356	        }
357	
358	        if ($null -ne $this.Explicit -and
359	            $this.Explicit -ne $currentSource.Explicit)
360	        {
361	            return $false
362	        }
363	
364	        if ($null -ne $this.Priority -and
365	            $this.Priority -ne $currentSource.Priority)
366	        {
367	            return $false
368	        }
369	
370	        return $true
371	    }
372	}
