465	class WinGetPackage
466	{
467	    [DscProperty(Key, Mandatory)]
468	    [string]$Id
469	
470	    [DscProperty(Key)]
471	    [string]$Source
472	
473	    [DscProperty()]
474	    [string]$Version
475	
476	    [DscProperty()]
477	    [WinGetEnsure]$Ensure = [WinGetEnsure]::Present
478	
479	    [DscProperty()]
480	    [WinGetMatchOption]$MatchOption = [WinGetMatchOption]::EqualsCaseInsensitive
481	
482	    [DscProperty()]
483	    [bool]$UseLatest = $false
484	
485	    [DSCProperty()]
486	    [WinGetInstallMode]$InstallMode = [WinGetInstallMode]::Silent
487	
488	    [PSObject] hidden $CatalogPackage = $null
489	
490	    [WinGetPackage] Get()
491	    {
492	        if ([String]::IsNullOrWhiteSpace($this.Id))
493	        {
494	            throw "A value must be provided for WinGetPackage::Id"
495	        }
496	
497	        $result = [WinGetPackage]::new()
498	
499	        $hashArgs = @{
500	            Id = $this.Id
501	            MatchOption = $this.MatchOption
502	        }
503	
504	        if (-not([string]::IsNullOrWhiteSpace($this.Source)))
505	        {
506	            $hashArgs.Add("Source", $this.Source)
507	        }
508	
509	        $result.CatalogPackage = Get-WinGetPackage @hashArgs
510	        if ($null -ne $result.CatalogPackage)
511	        {
512	            $result.Ensure = [WinGetEnsure]::Present
513	            $result.Id = $result.CatalogPackage.Id
514	            $result.Source = $result.CatalogPackage.Source
515	            $result.Version = $result.CatalogPackage.InstalledVersion
516	            $result.UseLatest = -not $result.CatalogPackage.IsUpdateAvailable
517	        }
518	        else
519	        {
520	            $result.Ensure = [WinGetEnsure]::Absent
521	            $result.Id = $this.Id
522	            $result.MatchOption = $this.MatchOption
523	            $result.Source = $this.Source
524	        }
525	
526	        return $result
527	    }
528	
529	    [bool] Test()
530	    {
531	        return $this.TestAgainstCurrent($this.Get())
532	    }
533	
534	    [void] Set()
535	    {
536	        $currentPackage = $this.Get()
537	
538	        if (-not $this.TestAgainstCurrent($currentPackage))
539	        {
540	            $hashArgs = @{
541	                Id = $this.Id
542	                MatchOption = $this.MatchOption
543	                Mode = $this.InstallMode
544	            }
545	            
546	            if ($this.Ensure -eq [WinGetEnsure]::Present)
547	            {
548	                if (-not([string]::IsNullOrWhiteSpace($this.Source)))
549	                {
550	                    $hashArgs.Add("Source", $this.Source)
551	                }
552	
553	                if ($currentPackage.Ensure -eq [WinGetEnsure]::Present)
554	                {
555	                    if ($this.UseLatest)
556	                    {
557	                        $this.TryUpdate($hashArgs)
558	                    }
559	                    elseif (-not([string]::IsNullOrWhiteSpace($this.Version)))
560	                    {
561	                        $hashArgs.Add("Version", $this.Version)
562	
563	                        $compareResult = $currentPackage.CatalogPackage.CompareToVersion($this.Version)
564	                        switch ($compareResult)
565	                        {
566	                            'Lesser'
567	                            {
568	                                $this.TryUpdate($hashArgs)
569	                                break
570	                            }
571	                            {'Greater' -or 'Unknown'}
572	                            {
573	                                # The installed package has a greater version or unknown. Uninstall and install.
574	                                $this.Uninstall()
575	                                $this.Install($hashArgs)
576	                                break
577	                            }
578	                        }
579	                    }
580	                }
581	                else
582	                {
583	                    if (-not([string]::IsNullOrWhiteSpace($this.Version)))
584	                    {
585	                        $hashArgs.Add("Version", $this.Version)
586	                    }
587	
588	                    $this.Install($hashArgs)
589	                }
590	            }
591	            else
592	            {
593	                $this.Uninstall()
594	            }
595	        }
596	    }
597	    
598	    [bool] hidden TestAgainstCurrent([WinGetPackage]$currentPackage)
599	    {
600	        if ($this.Ensure -eq [WinGetEnsure]::Absent -and
601	            $currentPackage.Ensure -eq [WinGetEnsure]::Absent)
602	        {
603	            return $true
604	        }
605	
606	        $this.CatalogPackage = $currentPackage.CatalogPackage
607	
608	        if ($this.Ensure -ne $currentPackage.Ensure)
609	        {
610	            return $false
611	        }
612	
613	        # At this point we know is installed.
614	        # If asked for latest, but there are updates available.
615	        if ($this.UseLatest)
616	        {
617	            if (-not $currentPackage.UseLatest)
618	            {
619	                return $false
620	            }
621	        }
622	        # If there is an specific version, compare with the current installed version.
623	        elseif (-not ([string]::IsNullOrWhiteSpace($this.Version)))
624	        {
625	            $compareResult = $currentPackage.CatalogPackage.CompareToVersion($this.Version)
626	            if ($compareResult -ne 'Equal')
627	            {
628	                return $false
629	            }
630	        }
631	
632	        return $true
633	    }
634	
635	    hidden Install([Hashtable]$hashArgs)
636	    {
637	        $installResult = Install-WinGetPackage @hashArgs
638	        if (-not $installResult.Succeeded())
639	        {
640	            # TODO: Localize.
641	            throw "WinGetPackage Failed installing $($this.Id). $($installResult.ErrorMessage())"
642	        }
643	    }
644	
645	    hidden Uninstall()
646	    {
647	        $uninstallResult = Uninstall-WinGetPackage -PSCatalogPackage $this.CatalogPackage
648	        if (-not $uninstallResult.Succeeded())
649	        {
650	            # TODO: Localize.
651	            throw "WinGetPackage Failed uninstalling $($this.Id). $($uninstallResult.ErrorMessage())"
652	        }
653	    }
654	
655	    hidden Update([Hashtable]$hashArgs)
656	    {
657	        $updateResult = Update-WinGetPackage @hashArgs
658	        if (-not $updateResult.Succeeded())
659	        {
660	            # TODO: Localize.
661	            throw "WinGetPackage Failed updating $($this.Id). $($updateResult.ErrorMessage())"
662	        }
663	    }
664	
665	    # Tries to update, if not, uninstall and install.
666	    hidden TryUpdate([Hashtable]$hashArgs)
667	    {
668	        try
669	        {
670	            $this.Update($hashArgs)
671	        }
672	        catch
673	        {
674	            $this.Uninstall()
675	            $this.Install($hashArgs)
676	        }
677	    }
678	}
